from fractions import Fraction as F
c = 20  # the parameter (was 15)
def f(x, p):
    return abs(x - p) + abs(x - c) + abs(x - p - c)
# on p <= x <= c: f(x) = (x - p) + (c - x) + (p + c - x) = 2c - x, decreasing, so the minimum is f(c) = c
for p in [F(k, 7) for k in range(1, 7 * c)]:
    xs = [p + (c - p) * F(i, 400) for i in range(401)]
    assert all(f(x, p) == 2 * c - x for x in xs)
    assert min(f(x, p) for x in xs) == c == f(F(c), p)
print(c)

R = 4  # f(n) = d(n) / n^(1/R) (was R = 3)
def primes(m):
    return [p for p in range(2, m) if all(p % q for q in range(2, int(p ** 0.5) + 1))]
# f is multiplicative: f(n) = prod_p g_p(e_p), g_p(e) = (e+1)/p^(e/R); compare exactly via g(e) > g(e') <=> (e+1)^R p^e' > (e'+1)^R p^e
def better(p, e, e2):
    return (e + 1) ** R * p ** e2 > (e2 + 1) ** R * p ** e
N = 1
for p in primes(2000):
    best = 0
    for e in range(1, 80):
        if better(p, e, best):
            best = e
    # the optimum must be strict (unique maximiser)
    assert all(better(p, best, e) for e in range(0, 80) if e != best)
    if p >= 2 ** R + 1:
        assert best == 0  # (e+1)^R < p^e for e >= 1 when p > 2^R
    N *= p ** best
print(N)
print(sum(int(c) for c in str(N)))
